  browser.context.deferCompletionSubmit(completionForm());
  assert.deepEqual(browser.navigations, []);
  await flush();
  assert.equal(browser.requests[0].options.body.get('completed'), '1');
  browser.resolve();
  await flush();
  assert.deepEqual(browser.navigations, []);
  await browser.runTimer();
  assert.deepEqual(browser.navigations, []);
